yI(a){return"\u062e\u0627\u0631\u062c \u0627\u0644\u0645\u0646\u0637\u0642\u0629: \u0639\u0644\u0649 \u0628\u064f\u0639\u062f "+a+" \u0645 \u0628\u0639\u062f \u0623\u0642\u0631\u0628 \u0645\u0646\u0637\u0642\u0629 \u0622\u0645\u0646\u0629."},
yW(a,b){return"\u0623\u0646\u062a \u062f\u0627\u062e\u0644 \u0645\u0646\u0637\u0642\u0629 \u0622\u0645\u0646\u0629 (\u0639\u0644\u0649 \u0628\u064f\u0639\u062f "+a+" \u0645 \u0645\u0646 \u0627\u0644\u062d\u0627\u0641\u0629). \u0627\u0628\u062a\u0639\u062f \u0623\u0643\u062b\u0631 \u0645\u0646 "+b+" \u0645 \u0644\u0628\u062f\u0621 \u0631\u062d\u0644\u0629."},
yZ(a,b){return"\u0623\u0646\u062a \u0639\u0644\u0649 \u0628\u064f\u0639\u062f "+a+" \u0645 \u0628\u0639\u062f \u0627\u0644\u062d\u062f\u0648\u062f \u2014 \u0641\u0648\u0642 \u0639\u062a\u0628\u0629 \u0627\u0644\u0625\u062b\u0628\u0627\u062a ("+b+" \u0645\u060c \u0628\u0645\u0627 \u064a\u0634\u0645\u0644 \u062f\u0642\u0629 \u0627\u0644\u0642\u064a\u0627\u0633): \u0633\u064a\u0628\u062f\u0623 \u0627\u0644\u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062a\u0644\u0642\u0627\u0626\u064a \u0647\u0646\u0627 (3 \u0642\u064a\u0627\u0633\u0627\u062a \u0628\u0641\u0627\u0635\u0644 ~10 \u062b\u0648\u0627\u0646\u064d)."},
yX(a,b){return"\u0623\u0646\u062a \u062e\u0627\u0631\u062c \u0627\u0644\u0645\u0646\u0637\u0642\u0629 ("+a+" \u0645 \u0628\u0639\u062f \u0627\u0644\u062d\u062f\u0648\u062f)\u060c \u0644\u0643\u0646 \u0647\u0630\u0627 \u0627\u0644\u0642\u064a\u0627\u0633 \u0644\u0627 \u064a\u0633\u062a\u0637\u064a\u0639 \u0625\u062b\u0628\u0627\u062a \u0630\u0644\u0643 \u0628\u0639\u062f: \u0628\u062f\u0642\u062a\u0647 \u0627\u0644\u062d\u0627\u0644\u064a\u0629 \u064a\u062c\u0628 \u062a\u062c\u0627\u0648\u0632 "+b+" \u0645. \u0627\u0628\u062a\u0639\u062f \u0623\u0643\u062b\u0631 \u0623\u0648 \u0627\u0646\u062a\u0638\u0631 \u0642\u064a\u0627\u0633\u064b\u0627 \u0623\u062f\u0642."},
gyR(){return"\u062e\u0627\u0631\u062c \u0627\u0644\u0645\u0646\u0637\u0642\u0629 \u2014 \u064a\u062c\u0631\u064a \u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u0645\u0633\u0627\u0631 \u0627\u0644\u062a\u0644\u0642\u0627\u0626\u064a (\u0645\u062e\u062a\u0648\u0645)."},
gyQ(){return"\u062f\u0627\u062e\u0644 \u0627\u0644\u0645\u0646\u0637\u0642\u0629 \u2014 \u0644\u0627 \u064a\u0648\u062c\u062f \u0645\u0633\u0627\u0631 \u062a\u0644\u0642\u0627\u0626\u064a \u0642\u064a\u062f \u0627\u0644\u062a\u0633\u062c\u064a\u0644."},
gBk(){return"\u0644\u0645 \u064a\u0642\u062f\u0645 \u0627\u0644\u0634\u062e\u0635 \u0627\u0644\u0645\u062d\u0645\u064a \u0623\u064a \u062a\u0641\u0627\u0635\u064a\u0644 (\u0644\u0627 \u0645\u0631\u0627\u0641\u0642 \u0648\u0644\u0627 \u0645\u0631\u0643\u0628\u0629 \u0648\u0644\u0627 \u0631\u0633\u0627\u0644\u0629) \u2014 \u062a\u0645\u062a \u0645\u0634\u0627\u0631\u0643\u0629 \u0625\u0634\u0627\u0631\u0629 \u0627\u0644\u0645\u0631\u0627\u0641\u0642\u0629 \u0641\u0642\u0637."},
gqv(){return"\u0644\u0642\u062f \u0648\u0635\u0644\u062a\u064f \u0628\u0623\u0645\u0627\u0646"},
gBf(){return"\u062a\u0623\u0643\u064a\u062f: \u0648\u0635\u0644\u062a\u064f \u0628\u0623\u0645\u0627\u0646 \u2014 \u062a\u0646\u062a\u0647\u064a \u0627\u0644\u0645\u0631\u0627\u0641\u0642\u0629."},
gBg(){return"\u062a\u0645 \u2014 \u0627\u0646\u062a\u0647\u062a \u0627\u0644\u0645\u0631\u0627\u0641\u0642\u0629."},
yB(a,b){return"\u0622\u062e\u0631 \u0645\u0648\u0642\u0639: \u0645\u0646\u0630 "+a+" (\u062f\u0642\u0629 "+b+" \u0645)"},
gyJ(){return"\u0644\u0645 \u064a\u064f\u0642\u064e\u0633 \u0623\u064a \u0645\u0648\u0642\u0639 \u0628\u0639\u062f."},
gte(){return"\u062a\u062d\u0642\u0642 \u0645\u0646 \u062d\u0627\u0644\u0629 \u0627\u0644\u062d\u0645\u0627\u064a\u0629"},
He(a){return"\u0623\u064f\u062d\u064a\u0644 \u0627\u0644\u0645\u0644\u0641 \u0625\u0644\u0649 \u0645\u0631\u0643\u0632 \u0627\u0644\u062a\u0646\u0638\u064a\u0645 (17) \u0628\u0648\u0627\u0633\u0637\u0629 "+a},
Hd(a){return"\u0623\u064f\u062d\u064a\u0644 \u0627\u0644\u0645\u0644\u0641 \u0625\u0644\u0649 \u062c\u0647\u0629 \u0627\u0644\u062a\u062d\u0642\u064a\u0642 \u0628\u0648\u0627\u0633\u0637\u0629 "+a},
