Hh(a){return"\u0627\u0633\u062a\u0624\u0646\u0641\u062a \u0627\u0644\u0625\u062d\u0627\u0644\u0629 \u0646\u062d\u0648 \u062c\u0647\u0629 \u0623\u062e\u0631\u0649 \u0628\u0648\u0627\u0633\u0637\u0629 "+a},
GY(a){return"\u062a\u0648\u0644\u0649 "+a+" \u0627\u0644\u0645\u0644\u0641"},
GZ(a){return"\u0631\u0641\u0639 "+a+" \u0627\u0644\u0623\u0645\u0631 \u0625\u0644\u0649 \u0627\u0644\u0646\u064a\u0627\u0628\u0629"},
H4(a){return"\u0627\u0637\u0644\u0639 "+a+" \u0639\u0644\u0649 \u0627\u0644\u062e\u062a\u0645 GPS"},
H5(a){return"\u0627\u0637\u0644\u0639 "+a+" \u0639\u0644\u0649 \u062e\u062a\u0645 \u0627\u0644\u0635\u0648\u0631"},
H9(a){return"\u0646\u0632\u0651\u0644 "+a+" \u0639\u0646\u0635\u0631\u064b\u0627 \u0645\u0646 \u0627\u0644\u062e\u062a\u0645"},
H0(a){return"\u0635\u062f\u0651\u0631 "+a+" \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a"},
H3(a){return"\u0623\u062c\u0631\u0649 "+a+" \u0627\u0644\u0627\u0633\u062a\u062e\u0631\u0627\u062c"},
GV(a){return"\u0627\u0637\u0644\u0639 "+a+" \u0639\u0644\u0649 \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0627\u0644\u0645\u0631\u0627\u0641\u0642\u0629"},
GW(a){return"\u0646\u0634\u0631 "+a+" \u0628\u0644\u0627\u063a \u0627\u0644\u0628\u062d\u062b"},
H1(a){return"\u0623\u063a\u0644\u0642 "+a+" \u0627\u0644\u0645\u0644\u0641"},
gHg(){return"\u0644\u0645 \u064a\u064f\u062a\u0648\u0644\u064e\u0651 \u0641\u064a \u0627\u0644\u0645\u0647\u0644\u0629 \u2014 \u0633\u064f\u062d\u0628 \u0627\u0644\u0645\u0644\u0641 \u062a\u0644\u0642\u0627\u0626\u064a\u064b\u0627"},
