gLG(){return"\u0623\u062d\u062f \u0627\u0644\u062d\u0645\u0627\u0629"},
gLF(){return"\u0623\u062d\u062f \u0627\u0644\u0645\u062d\u0642\u0642\u064a\u0646"},
gLD(){return"\u0627\u0644\u0646\u064a\u0627\u0628\u0629"},
