gLC(){return"\u0627\u0644\u0625\u062f\u0627\u0631\u0629"},
gIa(){return"\u062a\u0630\u0643\u064a\u0631: \u0645\u0644\u0641 \u0628\u0627\u0646\u062a\u0638\u0627\u0631 \u062a\u0648\u0644\u064a\u0643\u0645"},
gC1(){return"\u0645\u062a\u0627\u0628\u0639\u0629 \u0627\u0644\u0625\u062c\u0631\u0627\u0621 \u0627\u0644\u062c\u0627\u0631\u064a"},
gCe(){return"\u0623\u064f\u062d\u064a\u0644 \u0627\u0644\u0625\u062c\u0631\u0627\u0621 \u0625\u0644\u0649 \u0627\u0644\u0645\u062d\u0642\u0642\u064a\u0646 \u2014 \u0627\u0646\u0638\u0631 \u0627\u0644\u0645\u062a\u0627\u0628\u0639\u0629"},
gCb(){return"\u0628\u0637\u0627\u0642\u0629 \u0627\u0644\u0645\u062d\u0645\u064a (\u0635\u0648\u0631\u0629\u060c \u0623\u0648\u0635\u0627\u0641)"},
gMH(){return"\u0647\u0646\u0627\u0643 \u062a\u0646\u0628\u064a\u0647 \u062c\u0627\u0631\u064d: \u0633\u064a\u064f\u0631\u0641\u0642 \u0648\u0642\u062a \u0625\u0637\u0644\u0627\u0642\u0647 \u0648\u0645\u0648\u0642\u0639\u0647 \u0648\u062a\u0648\u0644\u0651\u064a\u0647 \u0628\u0627\u0644\u0645\u0644\u0641 \u0627\u0644\u0623\u0648\u0644\u064a."},
gDU(){return"\u062a\u0639\u0630\u0651\u0631 \u0627\u0644\u062d\u0641\u0638 \u2014 \u062a\u062d\u0642\u0651\u0642 \u0645\u0646 \u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u062b\u0645 \u0623\u0639\u062f \u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629."},
gCo(){return"\u062a\u0639\u0630\u0651\u0631 \u062a\u0633\u062c\u064a\u0644 \u062a\u0648\u0644\u064a\u0643 \u0644\u0644\u062a\u0646\u0628\u064a\u0647. \u062a\u062d\u0642\u0651\u0642 \u0645\u0646 \u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u062b\u0645 \u0623\u0639\u062f \u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629."},
gCi(){return"\u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629"},
gC2(){return"\u0627\u0644\u0645\u0648\u0642\u0639 \u0639\u0628\u0631 GPS"},
gue(){return"\u0625\u0634\u0627\u0631\u0629 \u062a\u0644\u0642\u0627\u0626\u064a\u0629: \u0644\u0627 \u062a\u062a\u0628\u0651\u0639 \u0645\u0628\u0627\u0634\u0631."},
C5(a){return"\u0627\u0644\u0645\u0648\u0642\u0639 \u0627\u0644\u0645\u0628\u0627\u0634\u0631 \u2014 \u0642\u0628\u0644 "+a+" \u062b"},
ul(a){return"\u0627\u0644\u0645\u0648\u0642\u0639 \u0639\u0646\u062f \u0625\u0637\u0644\u0627\u0642 \u0627\u0644\u062a\u0646\u0628\u064a\u0647 \u2014 "+a},
C4(a){return"\u0622\u062e\u0631 \u0645\u0648\u0642\u0639 \u0645\u0639\u0631\u0648\u0641 \u2014 "+a},
